-- Club challenges: 500-catalog + owner-activated runs with deadline and prize.

CREATE TABLE IF NOT EXISTS public.e_club_challenge_difficulties (
  value text PRIMARY KEY,
  description text NOT NULL
);
ON CONFLICT (value) DO NOTHING;

CREATE TABLE IF NOT EXISTS public.club_challenge_catalog (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  difficulty text NOT NULL REFERENCES public.e_club_challenge_difficulties(value),
  category text NOT NULL,
  title text NOT NULL,
  title_fa text NOT NULL,
  description text NOT NULL DEFAULT '',
  description_fa text NOT NULL DEFAULT '',
  sort_order integer NOT NULL
);

CREATE TABLE IF NOT EXISTS public.club_challenges (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  club_id uuid NOT NULL REFERENCES public.clubs(id) ON UPDATE CASCADE ON DELETE CASCADE,
  catalog_id uuid NOT NULL REFERENCES public.club_challenge_catalog(id) ON UPDATE CASCADE ON DELETE RESTRICT,
  created_by_steam_id bigint NOT NULL REFERENCES public.players(steam_id) ON UPDATE CASCADE ON DELETE CASCADE,
  ends_at timestamptz NOT NULL,
  prize_ypoints integer,
  prize_other text NOT NULL DEFAULT '',
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT club_challenges_prize_present CHECK (
    COALESCE(prize_ypoints, 0) > 0 OR btrim(prize_other) <> ''
  ),
  CONSTRAINT club_challenges_ypoints_nonneg CHECK (
    prize_ypoints IS NULL OR prize_ypoints >= 0
  )
);
CREATE INDEX IF NOT EXISTS club_challenges_club_active_idx
  ON public.club_challenges (club_id, active, ends_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS club_challenges_one_active_catalog
  ON public.club_challenges (club_id, catalog_id)
  WHERE active;

CREATE OR REPLACE FUNCTION public.tbi_club_challenges()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT'
     OR (TG_OP = 'UPDATE' AND NEW.ends_at IS DISTINCT FROM OLD.ends_at) THEN
    IF NEW.ends_at <= now() THEN
      RAISE EXCEPTION 'Challenge end time must be in the future' USING ERRCODE = '22000';
    END IF;
  END IF;
  IF COALESCE(NEW.prize_ypoints, 0) <= 0 AND btrim(COALESCE(NEW.prize_other, '')) = '' THEN
    RAISE EXCEPTION 'Challenge needs a YPoint prize or another prize' USING ERRCODE = '22000';
  END IF;
  IF TG_OP = 'INSERT' AND NOT EXISTS (
    SELECT 1 FROM public.clubs c
     WHERE c.id = NEW.club_id AND c.owner_steam_id = NEW.created_by_steam_id
  ) THEN
    RAISE EXCEPTION 'Only the club owner can activate challenges' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS tbi_club_challenges ON public.club_challenges;
CREATE TRIGGER tbi_club_challenges
  BEFORE INSERT OR UPDATE ON public.club_challenges
  FOR EACH ROW EXECUTE FUNCTION public.tbi_club_challenges();

ON CONFLICT (code) DO NOTHING;
